import{c as a,S as r,j as n,m as l}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 6: Konsonantlar (Ünsüzler) ve Sınıflandırılması","description":"","frontmatter":{},"headers":[],"relativePath":"6 Konsonantlar (Ünsüzler) ve Sınıflandırılması.md","filePath":"6 Konsonantlar (Ünsüzler) ve Sınıflandırılması.md"}'),i={name:"6 Konsonantlar (Ünsüzler) ve Sınıflandırılması.md"};function s(t,e,o,k,u,d){return r(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="turk-dil-bilgisi-serisi-6-konsonantlar-unsuzler-ve-sınıflandırılması" tabindex="-1">Türk Dil Bilgisi Serisi - 6: Konsonantlar (Ünsüzler) ve Sınıflandırılması <a class="header-anchor" href="#turk-dil-bilgisi-serisi-6-konsonantlar-unsuzler-ve-sınıflandırılması" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 6: Konsonantlar (Ünsüzler) ve Sınıflandırılması”">​</a></h1><p>Ses bilgisi yolculuğumuzda vokalleri (ünlüleri) ve onların kusursuz uyumlarını geride bıraktık. Bu yazımızda, dilimizin iskeletini ve vurgu gücünü oluşturan <strong>Konsonantlar (Ünsüzler)</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre ünsüzler, ses yolunda mutlaka bir engelle karşılaşarak, bir sızma veya patlama gürültüsüyle oluşan seslerdir. Kendi başlarına hece kuramazlar ve net bir şekilde duyulabilmeleri için mutlaka bir vokalin yardımına ihtiyaç duyarlar.</p><hr><h2 id="_1-turkiye-turkcesinin-unsuz-kadrosu" tabindex="-1">1. Türkiye Türkçesinin Ünsüz Kadrosu <a class="header-anchor" href="#_1-turkiye-turkcesinin-unsuz-kadrosu" aria-label="Permalink to “1. Türkiye Türkçesinin Ünsüz Kadrosu”">​</a></h2><p>Modern alfabemizde yer alan ve Türkiye Türkçesinin temelini oluşturan <strong>21 ünsüz</strong> şunlardır: <strong>b, c, ç, d, f, g, ğ, h, j, k, l, m, n, p, r, s, ş, t, v, y, z</strong></p><blockquote><p><strong>Önemli Not:</strong> &quot;j&quot; sesi asli Türkçe kelimelerde kesinlikle bulunmaz. İçinde &quot;j&quot; olan kelimeler (Örn: <em>jandarma, reji, baret, viraj</em>) dilimize tamamen Batı dillerinden veya Farsçadan geçmiştir.</p></blockquote><hr><h2 id="_2-unsuzlerin-sınıflandırılması-tasnif-kriterleri" tabindex="-1">2. Ünsüzlerin Sınıflandırılması (Tasnif Kriterleri) <a class="header-anchor" href="#_2-unsuzlerin-sınıflandırılması-tasnif-kriterleri" aria-label="Permalink to “2. Ünsüzlerin Sınıflandırılması (Tasnif Kriterleri)”">​</a></h2><p>Muharrem Ergin sistematiğinde ünsüzler, tıpkı ünlüler gibi <strong>3 farklı kritere</strong> göre incelenir. Bu kriterler ünsüzlerin ağzımızdan çıkarken geçtiği fiziksel aşamaları gösterir.</p><h3 id="a-ses-tellerinin-durumuna-gore-sedalı-sedasız" tabindex="-1">A) Ses Tellerinin Durumuna Göre (Sedalı - Sedasız) <a class="header-anchor" href="#a-ses-tellerinin-durumuna-gore-sedalı-sedasız" aria-label="Permalink to “A) Ses Tellerinin Durumuna Göre (Sedalı - Sedasız)”">​</a></h3><p>Havanın gırtlaktan geçerken ses tellerini titretip titretmemesine göre yapılan, Türkçenin en önemli ünsüz ayrımıdır:</p><ol><li><strong>Sedalı (Tonlu / Yumuşak) Ünsüzler:</strong> Ses tellerinin birbirine yaklaşarak titremesiyle oluşan, müzikal tınısı yüksek seslerdir. <ul><li><strong>b, c, d, g, ğ, j, l, m, n, r, v, y, z</strong></li></ul></li><li><strong>Sedasız (Tonsuz / Sert) Ünsüzler:</strong> Ses telleri titreşmeden, sadece ağız içindeki sürtünme veya patlamayla oluşan sert seslerdir. (Halk arasında <em>Fıstıkçı Şahap</em> olarak kodlanır). <ul><li><strong>ç, f, h, k, p, s, ş, t</strong></li></ul></li></ol><h3 id="b-cıkıs-yerlerine-gore-tesekkul-noktaları" tabindex="-1">B) Çıkış Yerlerine Göre (Teşekkül Noktaları) <a class="header-anchor" href="#b-cıkıs-yerlerine-gore-tesekkul-noktaları" aria-label="Permalink to “B) Çıkış Yerlerine Göre (Teşekkül Noktaları)”">​</a></h3><p>Havanın ses yolunda tam olarak hangi organda engele/takıntıya uğradığını gösteren tasniftir:</p><ul><li><strong>Dudak Ünsüzleri:</strong> Dudakların kapanıp açılmasıyla oluşur: <strong>b, m, p</strong></li><li><strong>Diş-Dudak Ünsüzleri:</strong> Üst dişlerin alt dudağa değmesiyle oluşur: <strong>f, v</strong></li><li><strong>Diş Ünsüzleri:</strong> Dil ucunun üst dişlerin arkasına basmasıyla oluşur: <strong>c, ç, d, j, l, n, r, s, ş, t, z</strong></li><li><strong>Damak Ünsüzleri:</strong> Dil sırtının damakla temasıyla oluşur: <strong>g, ğ, k, y</strong></li><li><strong>Gırtlak Ünsüzü:</strong> Doğrudan doğruya gırtlaktaki daralmayla oluşur: <strong>h</strong></li></ul><h3 id="c-ses-yolunun-acılıs-sekline-gore-surekli-sureksiz" tabindex="-1">C) Ses Yolunun Açılış Şekline Göre (Sürekli - Süreksiz) <a class="header-anchor" href="#c-ses-yolunun-acılıs-sekline-gore-surekli-sureksiz" aria-label="Permalink to “C) Ses Yolunun Açılış Şekline Göre (Sürekli - Süreksiz)”">​</a></h3><p>Sesin çıkış anında havanın bir anda patlayarak mı çıktığı, yoksa sürtünerek sızmaya devam mı ettiğini belirleyen kriterdir:</p><ol><li><strong>Süreksiz (Patlamalı) Ünsüzler:</strong> Hava akımı ses yolunda tamamen durdurulur ve ardından birden patlatılarak bırakılır. Bu sesleri uzatamazsınız. <ul><li><strong>b, c, ç, d, g, k, p, t</strong></li></ul></li><li><strong>Sürekli (Sızıcı/Akıcı) Ünsüzler:</strong> Hava yolu tamamen kapanmaz, daralır. Hava bu darlıktan sürtünerek sızar, dolayısıyla ses istenildiği kadar uzatılabilir. <ul><li><strong>f, ğ, h, j, l, m, n, r, s, ş, v, y, z</strong></li></ul></li></ol><hr><h2 id="_3-muharrem-ergin-in-klasik-unsuz-tablosu" tabindex="-1">3. Muharrem Ergin&#39;in Klasik Ünsüz Tablosu <a class="header-anchor" href="#_3-muharrem-ergin-in-klasik-unsuz-tablosu" aria-label="Permalink to “3. Muharrem Ergin&#39;in Klasik Ünsüz Tablosu”">​</a></h2><p>Tüm bu özellikleri bir araya getirdiğimizde karşımıza çıkan ve Türkçenin ses olaylarını (benzeşme, yumuşama) çözmemizi sağlayan o meşhur tablo:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ses Yolunun Durumu</th><th style="text-align:center;">Sedasız (Sert) / Diş-Dudak-Gırtlak</th><th style="text-align:center;">Sedasız (Sert) / Damak</th><th style="text-align:center;">Sedalı (Yumuşak) / Dudak-Diş-Gırtlak</th><th style="text-align:center;">Sedalı (Yumuşak) / Damak</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Süreksiz (Patlamalı)</strong></td><td style="text-align:center;"><strong>p, t, ç</strong></td><td style="text-align:center;"><strong>k</strong></td><td style="text-align:center;"><strong>b, d, c</strong></td><td style="text-align:center;"><strong>g</strong></td></tr><tr><td style="text-align:left;"><strong>Sürekli (Sızıcı/Akıcı)</strong></td><td style="text-align:center;"><strong>f, h, s, ş</strong></td><td style="text-align:center;"></td><td style="text-align:center;"><strong>v, m, n, r, z, l, j</strong></td><td style="text-align:center;"><strong>ğ, y</strong></td></tr></tbody></table><hr><h2 id="_4-turkcenin-unsuz-ozellikleri-ve-kuralları" tabindex="-1">4. Türkçenin Ünsüz Özellikleri ve Kuralları <a class="header-anchor" href="#_4-turkcenin-unsuz-ozellikleri-ve-kuralları" aria-label="Permalink to “4. Türkçenin Ünsüz Özellikleri ve Kuralları”">​</a></h2><p>Asli Türkçe kelimeleri ilk bakışta yabancılardan ayırt etmemizi sağlayan çok katı ünsüz kuralları vardır:</p><ul><li><strong>Kelime Başında Bulunmayan Ünsüzler:</strong> Türkçe bir kelimenin başında <strong>c, ğ, j, l, m, n, r, z</strong> sesleri bulunmaz. <ul><li><em>İstisnalar:</em> Ne, niçin, neden gibi soru kelimeleri ve yansıma seslerden türeyen (<em>melemek, rüzgar -eski esinti kökenli-, zırıldamak</em>) kelimeler hariçtir.</li></ul></li><li><strong>Kelime Sonunda Bulunmayan Ünsüzler:</strong> Türkçe kelimelerin sonunda b, c, d, g yumuşak ünsüzleri bulunmaz. Bunların yerine sert karşılıkları olan <strong>p, ç, t, k</strong> bulunur (Örn: <em>Kitab</em> değil <em>Kitap</em>, <em>Ahad</em> değil <em>Ahmet/Anıt</em>).</li><li><strong>Yanyana İki Ünsüz:</strong> Türkçe kelime kökünde iki aynı ünsüz yanyana gelemez (Örn: <em>Millet, kuvvet, bakkal</em> Türkçe değildir).</li><li><strong>Kelime Başında Çift Ünsüz:</strong> Türkçe kelimeler çift ünsüzle başlayamaz (Örn: <em>Spor, tren, kral, plan</em> Türkçe değildir).</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Konsonantlar, Türkçenin konuşma dilindeki netliğini ve ritmini ayarlar. Kelime başındaki ve sonundaki katı ünsüz kuralları, dilimizin fonetik sınırlarını çizer. Bu kuralları bilmek, bir kelimenin Türkçe olup olmadığını bir saniyede anlamamızı sağlar.</p><p>Serimizin 7. bölümünde ses bilgisinin en hareketli konusuna geliyoruz: <strong>&quot;Türkçedeki Ses Hadiseleri&quot; (Ünsüz Yumuşaması, Benzeşmesi, Ses Düşmesi ve Türemesi)</strong>.</p><p>Sayfayı çevir aslanım, hız kesmek yok!</p>',32)])])}const z=a(i,[["render",s]]);export{g as __pageData,z as default};
